//! Tables generated by `build.rs`: the cosine tables of the NCO, the inverse-CDF table of the
//! `gauss_noise` kernel and (feature `static-twiddles`) the 4096-point FFT twiddles.
//!
//! The cosine tables are public so that backends can reproduce the table lookup of the
//! `rotate` and `fm_mod` kernels exactly.

// The generated file is plain data in the shortest round-trip notation of the
// build script, so the literal lints do not apply.
#![allow(clippy::unreadable_literal, clippy::excessive_precision)]

include!(concat!(env!("OUT_DIR"), "/tables.rs"));

/// `2 pi / 2^32` rounded to `f32`: the angle of one unit of the 32-bit oscillator phase. The
/// `C32` oscillator of `rotate` and `oscillate` multiplies the low 20 bits of the phase (the
/// distance to the table point below it, an integer, exact in `f32`) by it.
#[allow(clippy::cast_possible_truncation)]
pub const PHASE_UNIT_F32: f32 = (core::f64::consts::TAU / 4_294_967_296.0) as f32;
